def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split core version and pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            parsed_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    parsed_identifiers.append((0, int(ident)))  # 0 = numeric
                else:
                    parsed_identifiers.append((1, ident))  # 1 = string
        else:
            parsed_identifiers = None

        return (major, minor, patch, prerelease is not None, parsed_identifiers)

    def compare_key(v):
        major, minor, patch, has_prerelease, identifiers = parse_version(v)

        # Create a sort key
        # (major, minor, patch, has_prerelease_flag, prerelease_tuple)
        # has_prerelease_flag: False sorts after True (inverse for sorting)
        # So we use (not has_prerelease) to make versions without pre-release sort later

        if identifiers is None:
            # No pre-release: sorts after any pre-release of same version
            prerelease_key = (False, ())
        else:
            # Has pre-release: sorts before version without pre-release
            prerelease_key = (True, tuple(identifiers))

        return (major, minor, patch, prerelease_key)

    return sorted(versions, key=compare_key)

